import React, { useState, useEffect } from 'react';
import Login from './Login';
import Dashboard from './Dashboard';
import DataDiscovery from './DataDiscovery';
import Compliance from './Compliance';
import BreachAlert from './BreachAlert';
import './App.css';
function App() {
  const [activePage, setActivePage] = useState('dashboard');
  const [user, setUser] = useState(null);
  const [loading, setLoading] = useState(true);
  const [sidebarOpen, setSidebarOpen] = useState(true);

  useEffect(() => {
    const token = localStorage.getItem('token');
    const savedUser = localStorage.getItem('user');

    if (token && savedUser) {
      try {
        setUser(JSON.parse(savedUser));
      } catch (e) {
        localStorage.removeItem('token');
        localStorage.removeItem('user');
      }
    }
    setLoading(false);
  }, []);

  const handleLoginSuccess = (userData) => {
    setUser(userData);
    setActivePage('dashboard');
  };

  const handleLogout = () => {
    localStorage.removeItem('token');
    localStorage.removeItem('user');
    setUser(null);
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-screen bg-gray-50">
        <div className="text-center">
          <div className="text-4xl mb-4">📊</div>
          <p className="text-gray-600">Loading...</p>
        </div>
      </div>
    );
  }

  if (!user) {
    return <Login onLoginSuccess={handleLoginSuccess} />;
  }

  const navItems = [
    { id: 'dashboard', label: 'Dashboard', icon: '🏠' },
    { id: 'discovery', label: 'Data Discovery', icon: '📊' },
    { id: 'compliance', label: 'Compliance', icon: '✓' },
    { id: 'breach', label: 'Breach Alert', icon: '🚨' },
  ];

  return (
    <div className="flex h-screen bg-gray-100">
      {/* SIDEBAR */}
      <div className={`${sidebarOpen ? 'w-64' : 'w-20'} bg-gradient-to-b from-blue-900 to-blue-800 text-white shadow-lg transition-all duration-300 flex flex-col`}>
        {/* Logo */}
        <div className="p-6 border-b border-blue-700">
          <div className="flex items-center gap-3">
            <div className="text-3xl">📊</div>
            {sidebarOpen && <div className="font-bold text-xl">DPDP</div>}
          </div>
          {sidebarOpen && <p className="text-xs text-blue-200 mt-2">Governance Platform</p>}
        </div>

        {/* Navigation */}
        <nav className="flex-1 p-4 space-y-2">
          {navItems.map((item) => (
            <button
              key={item.id}
              onClick={() => setActivePage(item.id)}
              className={`w-full flex items-center gap-3 px-4 py-3 rounded-lg transition-all duration-200 ${
                activePage === item.id
                  ? 'bg-blue-600 shadow-lg'
                  : 'hover:bg-blue-700'
              }`}
            >
              <span className="text-xl">{item.icon}</span>
              {sidebarOpen && <span className="font-medium">{item.label}</span>}
            </button>
          ))}
        </nav>

        {/* User Section */}
        <div className="p-4 border-t border-blue-700 space-y-3">
          <div className="bg-blue-700 rounded-lg p-3">
            {sidebarOpen && (
              <>
                <p className="text-sm font-semibold truncate">{user.username}</p>
                <p className="text-xs text-blue-200">{user.department}</p>
                <p className="text-xs bg-blue-600 inline-block px-2 py-1 rounded mt-2 font-medium">
                  {user.role.toUpperCase()}
                </p>
              </>
            )}
          </div>

          <button
            onClick={handleLogout}
            className="w-full bg-red-600 hover:bg-red-700 text-white font-medium py-2 px-4 rounded-lg transition-colors duration-200 flex items-center justify-center gap-2"
          >
            <span>🚪</span>
            {sidebarOpen && <span>Logout</span>}
          </button>

          <button
            onClick={() => setSidebarOpen(!sidebarOpen)}
            className="w-full bg-blue-700 hover:bg-blue-600 text-white py-2 px-4 rounded-lg transition-colors duration-200"
          >
            {sidebarOpen ? '◄' : '►'}
          </button>
        </div>
      </div>

      {/* MAIN CONTENT */}
      <div className="flex-1 flex flex-col">
        {/* TOP BAR */}
        <div className="bg-white shadow-sm border-b border-gray-200 px-8 py-4">
          <h1 className="text-2xl font-bold text-gray-900">
            {navItems.find(item => item.id === activePage)?.label}
          </h1>
        </div>

        {/* PAGE CONTENT */}
        <div className="flex-1 overflow-auto">
          <div className="p-8">
            {activePage === 'dashboard' && <Dashboard user={user} />}
            {activePage === 'discovery' && <DataDiscovery />}
            {activePage === 'compliance' && <Compliance />}
            {activePage === 'breach' && <BreachAlert />}
          </div>
        </div>
      </div>
    </div>
  );
}

export default App;
